import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import * as sass from 'sass';

/** Compile one authored source graph into page modules and a public-URL compatibility entrypoint. */
export function buildFrontendStyles( root, outputRoot ) {
	const source = path.join( root, 'assets/src/frontend' );
	const groups = JSON.parse(
		fs.readFileSync( path.join( source, 'styles.json' ), 'utf8' )
	);
	const destination = path.join( outputRoot, 'assets/css/frontend' );
	fs.mkdirSync( destination, { recursive: true } );
	const modules = [];
	const compile = ( imports, file ) => {
		const result = sass.compileString(
			imports.map( ( name ) => `@import '${ name }';` ).join( '\n' ),
			{
				loadPaths: [ path.join( source, 'scss' ) ],
				style: 'compressed',
				sourceMap: true,
				sourceMapIncludeSources: true,
			}
		);
		result.sourceMap.sources = result.sourceMap.sources.map( ( url ) =>
			url.startsWith( 'file:' )
				? 'ohmylms-source:///' +
					path
						.relative(
							path.join( root, 'assets/src' ),
							fileURLToPath( url )
						)
						.replaceAll( '\\', '/' )
				: 'ohmylms-source:///frontend/styles.json'
		);
		const css =
			result.css +
			'\n/*# sourceMappingURL=' +
			path.basename( file ) +
			'.map */\n';
		fs.writeFileSync( file, css );
		fs.writeFileSync( file + '.map', JSON.stringify( result.sourceMap ) );
		return {
			bytes: Buffer.byteLength( css ),
			version: crypto
				.createHash( 'sha256' )
				.update( css )
				.digest( 'hex' )
				.slice( 0, 12 ),
		};
	};
	for ( const [ name, imports ] of Object.entries( groups ) ) {
		const file = path.join( destination, name + '.css' );
		modules.push( {
			name,
			path: `assets/css/frontend/${ name }.css`,
			...compile( imports, file ),
		} );
	}
	fs.writeFileSync(
		path.join( destination, 'modules.json' ),
		JSON.stringify( modules, null, '\t' ) + '\n'
	);
	const php = modules
		.map(
			( item ) =>
				`\t'${ item.name }' => array( 'path' => '${ item.path }', 'version' => '${ item.version }', 'bytes' => ${ item.bytes } ),`
		)
		.join( '\n' );
	fs.writeFileSync(
		path.join( destination, 'modules.php' ),
		`<?php\n// Generated by tools/build-frontend-styles.mjs.\nreturn array(\n${ php }\n);\n`
	);
	// Older integrations may request these public URLs directly. Normal WordPress requests use modules.
	compile(
		Object.entries( groups )
			.filter( ( [ name ] ) => name !== 'rtl' )
			.flatMap( ( [ , imports ] ) => imports ),
		path.join( outputRoot, 'assets/css/style.css' )
	);
	compile( groups.rtl, path.join( outputRoot, 'assets/css/style-rtl.css' ) );
	return modules;
}
